def experiment(inputs):
    # Simplified scalarization check: Pareto efficiency vs scalar performance
    pareto_hits = inputs.get('pareto_hits', 0)
    scalar_score = inputs.get('scalar_score', 0)
    return {'measurements': {'scalar_divergence': [pareto_hits - scalar_score]}}

